// lib/cable-input.ts
import { z } from "zod";
var cableStandardSchema = z.enum([
  "usb_c",
  "jst_sh",
  "jst_ph",
  "us_mains"
]);
var color = z.string().regex(/^#[0-9a-fA-F]{6}$/);
var jacket = {
  jacketDiameter: z.number().finite().positive().default(4),
  color: color.default("#263449")
};
var cableInputSchema = z.discriminatedUnion("standard", [
  z.object({ standard: z.literal("usb_c"), ...jacket }).strict(),
  z.object({
    standard: z.literal("jst_sh"),
    pinCount: z.number().int().min(2).max(15).default(4),
    wireDiameter: z.number().finite().min(0.4).max(0.8).default(0.6)
  }).strict(),
  z.object({
    standard: z.literal("jst_ph"),
    pinCount: z.number().int().min(2).max(16).default(2),
    wireDiameter: z.number().finite().min(0.8).max(1.5).default(1.2)
  }).strict(),
  z.object({
    standard: z.literal("us_mains"),
    ...jacket,
    jacketDiameter: jacket.jacketDiameter.default(6.2)
  }).strict()
]);

// lib/cable-definition.ts
import { z as z2 } from "zod";
var dimension = z2.number().finite().positive();
var color2 = z2.string().regex(/^#[0-9a-fA-F]{6}$/);
var body = {
  bodyWidth: dimension,
  bodyHeight: dimension,
  bodyDepth: dimension
};
var cableConnectorSchema = z2.discriminatedUnion("kind", [
  z2.object({
    kind: z2.literal("usb_c_plug"),
    ...body,
    shellWidth: dimension,
    shellHeight: dimension,
    shellDepth: dimension
  }).strict(),
  z2.object({
    kind: z2.literal("jst_sh_housing"),
    ...body,
    pinCount: z2.number().int().min(2).max(15),
    pitch: z2.literal(1)
  }).strict(),
  z2.object({
    kind: z2.literal("jst_ph_housing"),
    ...body,
    pinCount: z2.number().int().min(2).max(16),
    pitch: z2.literal(2)
  }).strict(),
  z2.object({ kind: z2.literal("nema_5_15p"), ...body }).strict(),
  z2.object({ kind: z2.literal("iec_c13"), ...body }).strict()
]);
var cableCrossSectionSchema = z2.discriminatedUnion("kind", [
  z2.object({
    kind: z2.literal("round_jacket"),
    diameter: dimension,
    color: color2
  }).strict(),
  z2.object({
    kind: z2.literal("wire_bundle"),
    wires: z2.array(z2.object({ diameter: dimension, color: color2 }).strict()).min(2),
    wirePitch: dimension
  }).strict()
]);
var cableDefinitionSchema = z2.object({
  standard: cableStandardSchema,
  connectorA: cableConnectorSchema,
  connectorB: cableConnectorSchema,
  crossSection: cableCrossSectionSchema
}).strict().superRefine((cable, ctx) => {
  const { connectorA, connectorB, crossSection } = cable;
  const expected = {
    usb_c: ["usb_c_plug", "usb_c_plug"],
    jst_sh: ["jst_sh_housing", "jst_sh_housing"],
    jst_ph: ["jst_ph_housing", "jst_ph_housing"],
    us_mains: ["nema_5_15p", "iec_c13"]
  }[cable.standard];
  if (connectorA.kind !== expected[0] || connectorB.kind !== expected[1]) {
    ctx.addIssue({
      code: z2.ZodIssueCode.custom,
      message: "Connector kinds must match the cable standard"
    });
  }
  if (crossSection.kind === "wire_bundle") {
    for (const connector of [connectorA, connectorB]) {
      if (!("pinCount" in connector) || connector.pinCount !== crossSection.wires.length) {
        ctx.addIssue({
          code: z2.ZodIssueCode.custom,
          message: "Bundle wire count must match each connector pin count"
        });
      }
    }
    if (crossSection.wires.some(
      (wire) => wire.diameter > crossSection.wirePitch
    )) {
      ctx.addIssue({
        code: z2.ZodIssueCode.custom,
        message: "Bundle wires must not overlap in the cross section"
      });
    }
  } else if (cable.standard === "jst_sh" || cable.standard === "jst_ph") {
    ctx.addIssue({
      code: z2.ZodIssueCode.custom,
      message: "JST cables require a wire bundle"
    });
  }
});

// lib/get-cable-definition.ts
var wireColors = [
  "#df4049",
  "#263449",
  "#e1b13c",
  "#347dc9",
  "#27a782",
  "#af62bd"
];
function getCableDefinition(cableInput) {
  const cable = cableInputSchema.parse(cableInput);
  if (cable.standard === "usb_c") {
    const connector2 = {
      kind: "usb_c_plug",
      bodyWidth: 12,
      bodyHeight: 6,
      bodyDepth: 18,
      shellWidth: 8.25,
      shellHeight: 2.4,
      shellDepth: 6.5
    };
    return cableDefinitionSchema.parse({
      standard: cable.standard,
      connectorA: connector2,
      connectorB: { ...connector2 },
      crossSection: {
        kind: "round_jacket",
        diameter: cable.jacketDiameter,
        color: cable.color
      }
    });
  }
  if (cable.standard === "us_mains") {
    return cableDefinitionSchema.parse({
      standard: cable.standard,
      connectorA: {
        kind: "nema_5_15p",
        bodyWidth: 32,
        bodyHeight: 28,
        bodyDepth: 35
      },
      connectorB: {
        kind: "iec_c13",
        bodyWidth: 24,
        bodyHeight: 18,
        bodyDepth: 30
      },
      crossSection: {
        kind: "round_jacket",
        diameter: cable.jacketDiameter,
        color: cable.color
      }
    });
  }
  const isSh = cable.standard === "jst_sh";
  const connector = {
    kind: isSh ? "jst_sh_housing" : "jst_ph_housing",
    pinCount: cable.pinCount,
    pitch: isSh ? 1 : 2,
    bodyWidth: isSh ? cable.pinCount + 1 : (cable.pinCount - 1) * 2 + 3.8,
    bodyHeight: isSh ? 2.8 : 4.5,
    bodyDepth: isSh ? 5 : 6.85
  };
  return cableDefinitionSchema.parse({
    standard: cable.standard,
    connectorA: connector,
    connectorB: { ...connector },
    crossSection: {
      kind: "wire_bundle",
      wirePitch: connector.pitch,
      wires: Array.from({ length: cable.pinCount }, (_, index) => ({
        diameter: cable.wireDiameter,
        color: wireColors[index % wireColors.length]
      }))
    }
  });
}

// lib/parse-cable-string.ts
function parseCableString(cableString) {
  const cableName = cableString.trim().toLowerCase();
  if (cableName === "usb_c" || cableName === "us_mains") {
    return getCableDefinition({ standard: cableName });
  }
  const jstMatch = /^(jst_sh|jst_ph)(?:_pins([0-9]+))?$/.exec(cableName);
  if (jstMatch) {
    return getCableDefinition({
      standard: jstMatch[1] === "jst_sh" ? "jst_sh" : "jst_ph",
      ...jstMatch[2] ? { pinCount: Number(jstMatch[2]) } : {}
    });
  }
  throw new Error(
    `Unsupported cable string: "${cableString}". Expected usb_c, jst_sh[_pinsN], jst_ph[_pinsN], or us_mains.`
  );
}
export {
  cableConnectorSchema,
  cableCrossSectionSchema,
  cableDefinitionSchema,
  cableInputSchema,
  cableStandardSchema,
  getCableDefinition,
  parseCableString
};
